-- HomecoreOS Official Espressif & Partner Board Catalog + Visual Automation Flows

-- 1. Expand supported chip_family CHECK constraints across board_catalog, custom_boards, and firmware_releases
DO $$ DECLARE c RECORD; BEGIN
  FOR c IN SELECT conname FROM pg_constraint WHERE conrelid = 'public.board_catalog'::regclass AND contype = 'c' AND pg_get_constraintdef(oid) LIKE '%chip_family%' LOOP
    EXECUTE format('ALTER TABLE public.board_catalog DROP CONSTRAINT %I', c.conname);
  END LOOP;
  FOR c IN SELECT conname FROM pg_constraint WHERE conrelid = 'public.custom_boards'::regclass AND contype = 'c' AND pg_get_constraintdef(oid) LIKE '%chip_family%' LOOP
    EXECUTE format('ALTER TABLE public.custom_boards DROP CONSTRAINT %I', c.conname);
  END LOOP;
  FOR c IN SELECT conname FROM pg_constraint WHERE conrelid = 'public.firmware_releases'::regclass AND contype = 'c' AND pg_get_constraintdef(oid) LIKE '%chip_family%' LOOP
    EXECUTE format('ALTER TABLE public.firmware_releases DROP CONSTRAINT %I', c.conname);
  END LOOP;
END $$;

ALTER TABLE public.board_catalog ADD CONSTRAINT board_catalog_chip_family_check CHECK (chip_family IN ('esp32', 'esp32s2', 'esp32s3', 'esp32s31', 'esp32c2', 'esp32c3', 'esp32c5', 'esp32c6', 'esp32c61', 'esp32h2', 'esp32h21', 'esp32h4', 'esp32p4'));
ALTER TABLE public.custom_boards ADD CONSTRAINT custom_boards_chip_family_check CHECK (chip_family IN ('esp32', 'esp32s2', 'esp32s3', 'esp32s31', 'esp32c2', 'esp32c3', 'esp32c5', 'esp32c6', 'esp32c61', 'esp32h2', 'esp32h21', 'esp32h4', 'esp32p4'));
ALTER TABLE public.firmware_releases ADD CONSTRAINT firmware_releases_chip_family_check CHECK (chip_family IN ('esp32', 'esp32s2', 'esp32s3', 'esp32s31', 'esp32c2', 'esp32c3', 'esp32c5', 'esp32c6', 'esp32c61', 'esp32h2', 'esp32h21', 'esp32h4', 'esp32p4'));

-- 2. Extend board_catalog, custom_boards, and board_gpio_definitions for official hardware metadata & visual pinout layouts
ALTER TABLE public.board_catalog
  ADD COLUMN IF NOT EXISTS catalog_category TEXT NOT NULL DEFAULT 'official_espressif',
  ADD COLUMN IF NOT EXISTS series TEXT,
  ADD COLUMN IF NOT EXISTS image_url TEXT,
  ADD COLUMN IF NOT EXISTS pinout_image_url TEXT,
  ADD COLUMN IF NOT EXISTS docs_url TEXT,
  ADD COLUMN IF NOT EXISTS datasheet_url TEXT,
  ADD COLUMN IF NOT EXISTS source_url TEXT,
  ADD COLUMN IF NOT EXISTS source_provider TEXT NOT NULL DEFAULT 'manual',
  ADD COLUMN IF NOT EXISTS verification_status TEXT NOT NULL DEFAULT 'needs_verification',
  ADD COLUMN IF NOT EXISTS firmware_status TEXT NOT NULL DEFAULT 'catalog_only',
  ADD COLUMN IF NOT EXISTS board_layout JSONB NOT NULL DEFAULT '{}'::jsonb,
  ADD COLUMN IF NOT EXISTS revision_notes TEXT,
  ADD COLUMN IF NOT EXISTS last_synced_at TIMESTAMPTZ;

ALTER TABLE public.board_catalog DROP CONSTRAINT IF EXISTS board_catalog_category_check;
ALTER TABLE public.board_catalog ADD CONSTRAINT board_catalog_category_check CHECK (catalog_category IN ('official_espressif', 'partner', 'custom'));
ALTER TABLE public.board_catalog DROP CONSTRAINT IF EXISTS board_catalog_verification_check;
ALTER TABLE public.board_catalog ADD CONSTRAINT board_catalog_verification_check CHECK (verification_status IN ('verified', 'needs_verification'));
ALTER TABLE public.board_catalog DROP CONSTRAINT IF EXISTS board_catalog_firmware_status_check;
ALTER TABLE public.board_catalog ADD CONSTRAINT board_catalog_firmware_status_check CHECK (firmware_status IN ('firmware_supported', 'catalog_only', 'build_pending', 'unsupported'));

ALTER TABLE public.custom_boards
  ADD COLUMN IF NOT EXISTS catalog_category TEXT NOT NULL DEFAULT 'custom',
  ADD COLUMN IF NOT EXISTS image_url TEXT,
  ADD COLUMN IF NOT EXISTS docs_url TEXT,
  ADD COLUMN IF NOT EXISTS board_layout JSONB NOT NULL DEFAULT '{}'::jsonb;

ALTER TABLE public.board_gpio_definitions
  ADD COLUMN IF NOT EXISTS board_pin_name TEXT,
  ADD COLUMN IF NOT EXISTS header_side TEXT,
  ADD COLUMN IF NOT EXISTS header_position INT,
  ADD COLUMN IF NOT EXISTS board_note TEXT;

-- 3. Board catalog official sync audit runs
CREATE TABLE IF NOT EXISTS public.board_catalog_sync_runs (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  source_name TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('running', 'succeeded', 'partial', 'failed')),
  triggered_by_admin_id UUID REFERENCES public.users(id) ON DELETE SET NULL,
  discovered_count INT NOT NULL DEFAULT 0,
  inserted_count INT NOT NULL DEFAULT 0,
  updated_count INT NOT NULL DEFAULT 0,
  needs_verification_count INT NOT NULL DEFAULT 0,
  source_urls JSONB NOT NULL DEFAULT '[]'::jsonb,
  summary_notes TEXT,
  error_message TEXT,
  started_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  completed_at TIMESTAMPTZ
);
CREATE INDEX IF NOT EXISTS idx_board_sync_runs_started ON public.board_catalog_sync_runs (started_at DESC);

-- 4. Extend automation_rules for node-based visual flow graphs, folders, and execution traces
ALTER TABLE public.automation_rules
  ADD COLUMN IF NOT EXISTS folder_name TEXT NOT NULL DEFAULT 'General',
  ADD COLUMN IF NOT EXISTS flow_graph JSONB,
  ADD COLUMN IF NOT EXISTS flow_version INT NOT NULL DEFAULT 1,
  ADD COLUMN IF NOT EXISTS last_run_trace JSONB;
CREATE INDEX IF NOT EXISTS idx_automation_rules_folder ON public.automation_rules (account_id, folder_name) WHERE deleted_at IS NULL;

-- 5. Seed & update verified official Espressif and Seeed Studio partner boards with exact pin headers
WITH upsert_board AS (
  INSERT INTO public.board_catalog (
    slug, manufacturer, model, revision, chip_family, chip_variant,
    flash_size_mb, psram_size_mb, usb_vid, usb_pid, is_available, description,
    catalog_category, series, image_url, pinout_image_url, docs_url, datasheet_url,
    source_url, source_provider, verification_status, firmware_status,
    board_layout, revision_notes, last_synced_at
  ) VALUES (
    'esp32-s3-devkitc-1-n16r8', 'Espressif', 'ESP32-S3-DevKitC-1 N16R8', 'v1.1', 'esp32s3', 'ESP32-S3-WROOM-1-N16R8',
    16, 8, '0x303A', '0x1001', true, 'v1.1 uses GPIO38 for onboard WS2812 RGB LED (v1.0 used GPIO48). GPIO35-37 reserved for 8 MB Octal PSRAM.',
    'official_espressif', 'ESP32-S3', '/boards/esp32-s3-devkitc-1-n16r8.png', NULL, 'https://docs.espressif.com/projects/esp-dev-kits/en/latest/esp32s3/esp32-s3-devkitc-1/user_guide_v1.1.html', 'https://www.espressif.com/sites/default/files/documentation/esp32-s3-wroom-1_wroom-1u_datasheet_en.pdf',
    'https://www.espressif.com/products/devkits', 'espressif_devkits', 'verified', 'firmware_supported',
    '{"formFactor":"devkit","orientation":"vertical","aspectRatio":0.4603174603174603,"usbEdge":"bottom","usbLabel":"UART + Native USB-C","antennaEdge":"top","antennaLabel":"PCB Antenna","imageFrame":{"pinTopPct":14.5,"pinBottomPct":89.5},"hardwareSpecs":{"processor":"Dual-Core Xtensa LX7 (240 MHz)","wireless":"Wi-Fi 4, BLE 5.0","usb":"2x USB-C (UART + Native OTG)","usbPortCount":2,"usbConnector":"usb-c","buttons":"RST + BOOT","resetLabel":"RST","modulePackage":"wroom","hasUartBridge":true},"leftHeader":{"name":"J1","pins":[{"position":1,"headerName":"J1","pinName":"3V3","gpioPin":null,"kind":"power","voltage":"3.3V"},{"position":2,"headerName":"J1","pinName":"3V3","gpioPin":null,"kind":"power","voltage":"3.3V"},{"position":3,"headerName":"J1","pinName":"RST","gpioPin":null,"kind":"reset","note":"CHIP_PU / EN reset"},{"position":4,"headerName":"J1","pinName":"4","gpioPin":4,"kind":"gpio","aliases":["ADC1_CH3","TOUCH4"]},{"position":5,"headerName":"J1","pinName":"5","gpioPin":5,"kind":"gpio","aliases":["ADC1_CH4","TOUCH5"]},{"position":6,"headerName":"J1","pinName":"6","gpioPin":6,"kind":"gpio","aliases":["ADC1_CH5","TOUCH6"]},{"position":7,"headerName":"J1","pinName":"7","gpioPin":7,"kind":"gpio","aliases":["ADC1_CH6","TOUCH7"]},{"position":8,"headerName":"J1","pinName":"15","gpioPin":15,"kind":"gpio","aliases":["XTAL_32K_P"]},{"position":9,"headerName":"J1","pinName":"16","gpioPin":16,"kind":"gpio","aliases":["XTAL_32K_N"]},{"position":10,"headerName":"J1","pinName":"17","gpioPin":17,"kind":"gpio","aliases":["UART1_TX"]},{"position":11,"headerName":"J1","pinName":"18","gpioPin":18,"kind":"gpio","aliases":["UART1_RX"]},{"position":12,"headerName":"J1","pinName":"8","gpioPin":8,"kind":"gpio","aliases":["ADC1_CH7","TOUCH8"]},{"position":13,"headerName":"J1","pinName":"3","gpioPin":3,"kind":"gpio","aliases":["ADC1_CH2","TOUCH3"],"note":"Strapping (JTAG)"},{"position":14,"headerName":"J1","pinName":"46","gpioPin":46,"kind":"gpio","note":"Input-only strapping"},{"position":15,"headerName":"J1","pinName":"9","gpioPin":9,"kind":"gpio","aliases":["ADC1_CH8","TOUCH9"]},{"position":16,"headerName":"J1","pinName":"10","gpioPin":10,"kind":"gpio","aliases":["ADC1_CH9","TOUCH10"]},{"position":17,"headerName":"J1","pinName":"11","gpioPin":11,"kind":"gpio","aliases":["TOUCH11"]},{"position":18,"headerName":"J1","pinName":"12","gpioPin":12,"kind":"gpio","aliases":["TOUCH12"]},{"position":19,"headerName":"J1","pinName":"13","gpioPin":13,"kind":"gpio","aliases":["TOUCH13"]},{"position":20,"headerName":"J1","pinName":"14","gpioPin":14,"kind":"gpio","aliases":["TOUCH14"]},{"position":21,"headerName":"J1","pinName":"5V","gpioPin":null,"kind":"power","voltage":"5V"},{"position":22,"headerName":"J1","pinName":"G","gpioPin":null,"kind":"ground","voltage":"GND"}]},"rightHeader":{"name":"J3","pins":[{"position":1,"headerName":"J3","pinName":"G","gpioPin":null,"kind":"ground","voltage":"GND"},{"position":2,"headerName":"J3","pinName":"TX","gpioPin":43,"kind":"gpio","aliases":["U0TXD"],"note":"UART0 TX"},{"position":3,"headerName":"J3","pinName":"RX","gpioPin":44,"kind":"gpio","aliases":["U0RXD"],"note":"UART0 RX"},{"position":4,"headerName":"J3","pinName":"1","gpioPin":1,"kind":"gpio","aliases":["ADC1_CH0","TOUCH1"]},{"position":5,"headerName":"J3","pinName":"2","gpioPin":2,"kind":"gpio","aliases":["ADC1_CH1","TOUCH2"]},{"position":6,"headerName":"J3","pinName":"42","gpioPin":42,"kind":"gpio","aliases":["MTMS"]},{"position":7,"headerName":"J3","pinName":"41","gpioPin":41,"kind":"gpio","aliases":["MTDI"]},{"position":8,"headerName":"J3","pinName":"40","gpioPin":40,"kind":"gpio","aliases":["MTDO"]},{"position":9,"headerName":"J3","pinName":"39","gpioPin":39,"kind":"gpio","aliases":["MTCK"]},{"position":10,"headerName":"J3","pinName":"38","gpioPin":38,"kind":"gpio","note":"Onboard RGB LED (v1.1)"},{"position":11,"headerName":"J3","pinName":"37","gpioPin":37,"kind":"gpio","note":"Octal PSRAM (unavailable on R8)"},{"position":12,"headerName":"J3","pinName":"36","gpioPin":36,"kind":"gpio","note":"Octal PSRAM (unavailable on R8)"},{"position":13,"headerName":"J3","pinName":"35","gpioPin":35,"kind":"gpio","note":"Octal PSRAM (unavailable on R8)"},{"position":14,"headerName":"J3","pinName":"0","gpioPin":0,"kind":"gpio","note":"BOOT button & strapping"},{"position":15,"headerName":"J3","pinName":"45","gpioPin":45,"kind":"gpio","note":"Strapping (VDD_SPI)"},{"position":16,"headerName":"J3","pinName":"48","gpioPin":48,"kind":"gpio","note":"General GPIO"},{"position":17,"headerName":"J3","pinName":"47","gpioPin":47,"kind":"gpio"},{"position":18,"headerName":"J3","pinName":"21","gpioPin":21,"kind":"gpio"},{"position":19,"headerName":"J3","pinName":"20","gpioPin":20,"kind":"gpio","aliases":["USB_D+"],"note":"USB D+"},{"position":20,"headerName":"J3","pinName":"19","gpioPin":19,"kind":"gpio","aliases":["USB_D-"],"note":"USB D-"},{"position":21,"headerName":"J3","pinName":"G","gpioPin":null,"kind":"ground","voltage":"GND"},{"position":22,"headerName":"J3","pinName":"G","gpioPin":null,"kind":"ground","voltage":"GND"}]},"onboardFeatures":[{"label":"WS2812 RGB LED","gpioPin":38,"kind":"rgb_led","note":"GPIO38 on v1.1 revision"},{"label":"BOOT Button","gpioPin":0,"kind":"button","note":"GPIO0 active-low boot mode"},{"label":"Octal PSRAM","gpioPin":35,"kind":"psram","note":"GPIO35-37 reserved (N16R8)"}]}'::jsonb, 'v1.1 uses GPIO38 for onboard WS2812 RGB LED (v1.0 used GPIO48). GPIO35-37 reserved for 8 MB Octal PSRAM.', now()
  )
  ON CONFLICT (slug) DO UPDATE SET
    manufacturer = EXCLUDED.manufacturer,
    model = EXCLUDED.model,
    revision = EXCLUDED.revision,
    chip_family = EXCLUDED.chip_family,
    chip_variant = EXCLUDED.chip_variant,
    flash_size_mb = EXCLUDED.flash_size_mb,
    psram_size_mb = EXCLUDED.psram_size_mb,
    usb_vid = EXCLUDED.usb_vid,
    usb_pid = EXCLUDED.usb_pid,
    is_available = EXCLUDED.is_available,
    catalog_category = EXCLUDED.catalog_category,
    series = EXCLUDED.series,
    image_url = EXCLUDED.image_url,
    docs_url = EXCLUDED.docs_url,
    datasheet_url = EXCLUDED.datasheet_url,
    source_url = EXCLUDED.source_url,
    source_provider = EXCLUDED.source_provider,
    verification_status = EXCLUDED.verification_status,
    firmware_status = EXCLUDED.firmware_status,
    board_layout = EXCLUDED.board_layout,
    revision_notes = EXCLUDED.revision_notes,
    last_synced_at = EXCLUDED.last_synced_at
  RETURNING id
)
INSERT INTO public.board_gpio_definitions (
  board_catalog_id, pin, label, board_pin_name, header_side, header_position, board_note, capabilities, restrictions
)
SELECT
  upsert_board.id,
  (p->>'pin')::int,
  p->>'label',
  p->>'board_pin_name',
  p->>'header_side',
  CASE WHEN p->>'header_position' IS NOT NULL THEN (p->>'header_position')::int ELSE NULL END,
  p->>'board_note',
  p->'capabilities',
  p->'restrictions'
FROM upsert_board
