WITH upsert_board AS (
  INSERT INTO public.board_catalog (
    slug, manufacturer, model, revision, chip_family, chip_variant,
    flash_size_mb, psram_size_mb, usb_vid, usb_pid, is_available, description,
    catalog_category, series, image_url, pinout_image_url, docs_url, datasheet_url,
    source_url, source_provider, verification_status, firmware_status,
    board_layout, revision_notes, last_synced_at
  ) VALUES (
    'seeed-xiao-esp32s3', 'Seeed Studio', 'XIAO ESP32-S3', 'v1.0', 'esp32s3', 'ESP32-S3R8',
    8, 8, '0x2886', '0x0056', true, 'Ultra-compact 21x17.8mm thumb-sized board. Exposes 11 GPIO pins across 7+7 castellations; onboard orange USER_LED on GPIO21 (active-low). B2B GPIO41/42 are digital-only.',
    'partner', 'ESP32-S3', '/boards/seeed-xiao-esp32s3.png', NULL, 'https://wiki.seeedstudio.com/xiao_esp32s3_getting_started/', 'https://files.seeedstudio.com/wiki/SeeedStudio-XIAO-ESP32S3/res/esp32-s3_datasheet_en.pdf',
    'https://wiki.seeedstudio.com/xiao_esp32s3_getting_started/', 'seeed_partner', 'verified', 'catalog_only',
    '{"formFactor":"xiao","orientation":"vertical","aspectRatio":0.7911975435005117,"usbEdge":"top","usbLabel":"USB Type-C","antennaEdge":"bottom","antennaLabel":"U.FL / B2B","imageFrame":{"pinTopPct":18.5,"pinBottomPct":87.5},"hardwareSpecs":{"processor":"Dual-Core Xtensa LX7 (240 MHz)","wireless":"Wi-Fi 4, BLE 5.0","usb":"1x USB-C","usbPortCount":1,"usbConnector":"usb-c","buttons":"RESET + BOOT","resetLabel":"RESET","modulePackage":"xiao","hasUartBridge":false},"leftHeader":{"name":"Left (D0-D6)","pins":[{"position":1,"headerName":"Left","pinName":"D0 / A0","gpioPin":1,"kind":"gpio","aliases":["A0","D0","ADC1_CH0","TOUCH1"]},{"position":2,"headerName":"Left","pinName":"D1 / A1","gpioPin":2,"kind":"gpio","aliases":["A1","D1","ADC1_CH1","TOUCH2"]},{"position":3,"headerName":"Left","pinName":"D2 / A2","gpioPin":3,"kind":"gpio","aliases":["A2","D2","ADC1_CH2","TOUCH3"]},{"position":4,"headerName":"Left","pinName":"D3 / A3","gpioPin":4,"kind":"gpio","aliases":["A3","D3","ADC1_CH3","TOUCH4"]},{"position":5,"headerName":"Left","pinName":"D4 / SDA","gpioPin":5,"kind":"gpio","aliases":["A4","D4","SDA","ADC1_CH4"],"note":"I2C SDA"},{"position":6,"headerName":"Left","pinName":"D5 / SCL","gpioPin":6,"kind":"gpio","aliases":["A5","D5","SCL","ADC1_CH5"],"note":"I2C SCL"},{"position":7,"headerName":"Left","pinName":"D6 / TX","gpioPin":43,"kind":"gpio","aliases":["D6","TX","U0TXD"],"note":"UART TX (free GPIO)"}]},"rightHeader":{"name":"Right (Power / D7-D10)","pins":[{"position":1,"headerName":"Right","pinName":"5V","gpioPin":null,"kind":"power","voltage":"5V","note":"USB VBUS 5V"},{"position":2,"headerName":"Right","pinName":"GND","gpioPin":null,"kind":"ground","voltage":"GND"},{"position":3,"headerName":"Right","pinName":"3V3","gpioPin":null,"kind":"power","voltage":"3.3V","note":"Regulated 3.3V out"},{"position":4,"headerName":"Right","pinName":"D10 / MOSI","gpioPin":9,"kind":"gpio","aliases":["A10","D10","MOSI"],"note":"SPI MOSI"},{"position":5,"headerName":"Right","pinName":"D9 / MISO","gpioPin":8,"kind":"gpio","aliases":["A9","D9","MISO"],"note":"SPI MISO"},{"position":6,"headerName":"Right","pinName":"D8 / SCK","gpioPin":7,"kind":"gpio","aliases":["A8","D8","SCK"],"note":"SPI SCK"},{"position":7,"headerName":"Right","pinName":"D7 / RX","gpioPin":44,"kind":"gpio","aliases":["D7","RX","U0RXD"],"note":"UART RX (free GPIO)"}]},"onboardFeatures":[{"label":"USER LED","gpioPin":21,"kind":"led","note":"Orange LED active-low on GPIO21"},{"label":"BOOT Button","gpioPin":0,"kind":"button","note":"Top-right tactile BOOT button"},{"label":"USB Serial / JTAG","gpioPin":19,"kind":"usb","note":"GPIO19/20 USB Type-C"}]}'::jsonb, 'Ultra-compact 21x17.8mm thumb-sized board. Exposes 11 GPIO pins across 7+7 castellations; onboard orange USER_LED on GPIO21 (active-low). B2B GPIO41/42 are digital-only.', now()
  )
  ON CONFLICT (slug) DO UPDATE SET
    manufacturer = EXCLUDED.manufacturer,
    model = EXCLUDED.model,
    revision = EXCLUDED.revision,
    chip_family = EXCLUDED.chip_family,
    chip_variant = EXCLUDED.chip_variant,
