    firmware_status = EXCLUDED.firmware_status,
    board_layout = EXCLUDED.board_layout,
    revision_notes = EXCLUDED.revision_notes,
    last_synced_at = EXCLUDED.last_synced_at
  RETURNING id
)
INSERT INTO public.board_gpio_definitions (
