    'esp32-c6-devkitc-1', 'Espressif', 'ESP32-C6-DevKitC-1', 'v1.2', 'esp32c6', 'ESP32-C6-WROOM-1-N8',
    8, 0, '0x303A', '0x1001', true, 'RISC-V Wi-Fi 6 + BLE 5 + IEEE 802.15.4 (Thread/Zigbee). RGB LED on GPIO8; USB D-/D+ on GPIO12/13.',
    'official_espressif', 'ESP32-C6', '/boards/esp32-c6-devkitc-1.png', NULL, 'https://docs.espressif.com/projects/esp-dev-kits/en/latest/esp32c6/esp32-c6-devkitc-1/user_guide.html', 'https://www.espressif.com/sites/default/files/documentation/esp32-c6_datasheet_en.pdf',
    'https://www.espressif.com/products/devkits', 'espressif_devkits', 'verified', 'catalog_only',
    '{"formFactor":"devkit","orientation":"vertical","aspectRatio":0.4708994708994709,"usbEdge":"bottom","usbLabel":"UART + Native USB-C","antennaEdge":"top","antennaLabel":"PCB Antenna","imageFrame":{"pinTopPct":15,"pinBottomPct":87},"hardwareSpecs":{"processor":"Single-Core RISC-V (160 MHz)","wireless":"Wi-Fi 6, BLE 5.3, Zigbee / Thread","usb":"2x USB-C (UART + Native JTAG)","usbPortCount":2,"usbConnector":"usb-c","buttons":"RST + BOOT","resetLabel":"RST","modulePackage":"wroom","hasUartBridge":true},"leftHeader":{"name":"J1","pins":[{"position":1,"headerName":"J1","pinName":"3V3","gpioPin":null,"kind":"power","voltage":"3.3V"},{"position":2,"headerName":"J1","pinName":"RST","gpioPin":null,"kind":"reset","note":"CHIP_EN reset"},{"position":3,"headerName":"J1","pinName":"0","gpioPin":0,"kind":"gpio","aliases":["ADC1_CH0","XTAL_32K_P"]},{"position":4,"headerName":"J1","pinName":"1","gpioPin":1,"kind":"gpio","aliases":["ADC1_CH1","XTAL_32K_N"]},{"position":5,"headerName":"J1","pinName":"2","gpioPin":2,"kind":"gpio","aliases":["ADC1_CH2"]},{"position":6,"headerName":"J1","pinName":"3","gpioPin":3,"kind":"gpio","aliases":["ADC1_CH3"]},{"position":7,"headerName":"J1","pinName":"4","gpioPin":4,"kind":"gpio","aliases":["ADC1_CH4","MTMS"],"note":"Strapping"},{"position":8,"headerName":"J1","pinName":"5","gpioPin":5,"kind":"gpio","aliases":["ADC1_CH5","MTDI"],"note":"Strapping"},{"position":9,"headerName":"J1","pinName":"6","gpioPin":6,"kind":"gpio","aliases":["ADC1_CH6","MTCK"]},{"position":10,"headerName":"J1","pinName":"7","gpioPin":7,"kind":"gpio","aliases":["MTDO"]},{"position":11,"headerName":"J1","pinName":"10","gpioPin":10,"kind":"gpio"},{"position":12,"headerName":"J1","pinName":"11","gpioPin":11,"kind":"gpio"},{"position":13,"headerName":"J1","pinName":"8","gpioPin":8,"kind":"gpio","note":"Onboard RGB LED & strapping"},{"position":14,"headerName":"J1","pinName":"15","gpioPin":15,"kind":"gpio","note":"Strapping"},{"position":15,"headerName":"J1","pinName":"5V","gpioPin":null,"kind":"power","voltage":"5V"},{"position":16,"headerName":"J1","pinName":"G","gpioPin":null,"kind":"ground","voltage":"GND"}]},"rightHeader":{"name":"J3","pins":[{"position":1,"headerName":"J3","pinName":"G","gpioPin":null,"kind":"ground","voltage":"GND"},{"position":2,"headerName":"J3","pinName":"TX / 16","gpioPin":16,"kind":"gpio","note":"UART0 TX"},{"position":3,"headerName":"J3","pinName":"RX / 17","gpioPin":17,"kind":"gpio","note":"UART0 RX"},{"position":4,"headerName":"J3","pinName":"23","gpioPin":23,"kind":"gpio"},{"position":5,"headerName":"J3","pinName":"22","gpioPin":22,"kind":"gpio"},{"position":6,"headerName":"J3","pinName":"21","gpioPin":21,"kind":"gpio"},{"position":7,"headerName":"J3","pinName":"20","gpioPin":20,"kind":"gpio"},{"position":8,"headerName":"J3","pinName":"19","gpioPin":19,"kind":"gpio"},{"position":9,"headerName":"J3","pinName":"18","gpioPin":18,"kind":"gpio"},{"position":10,"headerName":"J3","pinName":"14","gpioPin":14,"kind":"gpio"},{"position":11,"headerName":"J3","pinName":"9","gpioPin":9,"kind":"gpio","note":"BOOT button & strapping"},{"position":12,"headerName":"J3","pinName":"13","gpioPin":13,"kind":"gpio","note":"USB D+"},{"position":13,"headerName":"J3","pinName":"12","gpioPin":12,"kind":"gpio","note":"USB D-"},{"position":14,"headerName":"J3","pinName":"G","gpioPin":null,"kind":"ground","voltage":"GND"},{"position":15,"headerName":"J3","pinName":"G","gpioPin":null,"kind":"ground","voltage":"GND"},{"position":16,"headerName":"J3","pinName":"G","gpioPin":null,"kind":"ground","voltage":"GND"}]},"onboardFeatures":[{"label":"WS2812 RGB LED","gpioPin":8,"kind":"rgb_led","note":"GPIO8 (also strapping pin)"},{"label":"BOOT Button","gpioPin":9,"kind":"button","note":"GPIO9 active-low boot mode"}]}'::jsonb, 'RISC-V Wi-Fi 6 + BLE 5 + IEEE 802.15.4 (Thread/Zigbee). RGB LED on GPIO8; USB D-/D+ on GPIO12/13.', now()
  )
  ON CONFLICT (slug) DO UPDATE SET
    manufacturer = EXCLUDED.manufacturer,
    model = EXCLUDED.model,
    revision = EXCLUDED.revision,
    chip_family = EXCLUDED.chip_family,
    chip_variant = EXCLUDED.chip_variant,
    flash_size_mb = EXCLUDED.flash_size_mb,
    psram_size_mb = EXCLUDED.psram_size_mb,
    usb_vid = EXCLUDED.usb_vid,
    usb_pid = EXCLUDED.usb_pid,
    is_available = EXCLUDED.is_available,
    catalog_category = EXCLUDED.catalog_category,
    series = EXCLUDED.series,
    image_url = EXCLUDED.image_url,
    docs_url = EXCLUDED.docs_url,
    datasheet_url = EXCLUDED.datasheet_url,
    source_url = EXCLUDED.source_url,
    source_provider = EXCLUDED.source_provider,
    verification_status = EXCLUDED.verification_status,
    firmware_status = EXCLUDED.firmware_status,
    board_layout = EXCLUDED.board_layout,
    revision_notes = EXCLUDED.revision_notes,
    last_synced_at = EXCLUDED.last_synced_at
  RETURNING id
)
INSERT INTO public.board_gpio_definitions (
  board_catalog_id, pin, label, board_pin_name, header_side, header_position, board_note, capabilities, restrictions
)
SELECT
  upsert_board.id,
  (p->>'pin')::int,
  p->>'label',
  p->>'board_pin_name',
  p->>'header_side',
  CASE WHEN p->>'header_position' IS NOT NULL THEN (p->>'header_position')::int ELSE NULL END,
  p->>'board_note',
  p->'capabilities',
  p->'restrictions'
